#pragma once
#include <string_view>
namespace spark {
inline constexpr std::string_view file_explorer_html=R"HTML(<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SPARK · Files</title>
<style>
:root{color-scheme:dark;--bg:#10151d;--panel:#171e29;--line:#2b3544;--text:#e5ecf5;--muted:#a2b1c4;--accent:#89dbbd}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px/1.6 system-ui,sans-serif}button,input{font:inherit}button,a,input{touch-action:manipulation}:focus-visible{outline:2px solid var(--accent);outline-offset:3px}a{color:var(--accent)}button,.download{border:1px solid var(--line);border-radius:6px;background:#202b38;color:var(--text);padding:7px 12px;cursor:pointer;text-decoration:none}button:hover,.download:hover{background:#2e3d4e}button:disabled{opacity:.45;cursor:wait}.primary{background:var(--accent);color:#10151d;border:0}.danger{color:#ffafb5}header{height:80px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);padding:0 28px;gap:16px}header strong{letter-spacing:.16em;font-size:21px}header span{color:var(--muted);margin-left:20px}.layout{display:grid;grid-template-columns:260px minmax(0,1fr);height:calc(100vh - 80px);height:calc(100dvh - 80px)}aside{background:var(--panel);border-right:1px solid var(--line);display:flex;flex-direction:column;min-height:0;padding:22px 12px}aside h2{font-size:11px;color:var(--muted);letter-spacing:.14em;text-transform:uppercase;margin:0 12px 16px}#folders{overflow:auto;flex:1}#folders a{display:block;padding:8px 12px;border-radius:6px;overflow-wrap:anywhere;text-decoration:none;color:var(--text)}#folders a[aria-current=page]{background:#233b39;color:var(--accent)}main{overflow:auto;padding:30px 34px;min-width:0}h1{font-size:28px;margin:8px 0}.muted{color:var(--muted)}#breadcrumb{display:flex;flex-wrap:wrap;gap:8px;align-items:center;font-size:13px}.toolbar{display:flex;flex-wrap:wrap;gap:10px;align-items:center;margin:22px 0}input{border:1px solid var(--line);border-radius:6px;padding:9px 12px;background:var(--bg);color:var(--text);max-width:100%}.toolbar input{margin-left:auto;min-width:200px}#drop{border:1px dashed #4c6b68;border-radius:10px;padding:18px 22px;color:var(--muted);margin-bottom:20px;background:#152322}#drop.drag{border-color:var(--accent);background:#233b39}#drop strong{color:var(--accent)}#status{min-height:25px;overflow-wrap:anywhere}#status.error{color:#ffafb5}progress{width:100%;height:6px;accent-color:var(--accent)}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:10px}table{width:100%;border-collapse:collapse;text-align:left}th{font-weight:500;font-size:12px;color:var(--muted);padding:12px 16px;background:var(--panel)}td{padding:14px 16px;border-top:1px solid var(--line);vertical-align:middle}td:first-child{min-width:160px;overflow-wrap:anywhere;max-width:420px}td:nth-child(2){white-space:nowrap}.name{border:0;background:none;padding:0;text-align:left;color:var(--text);overflow-wrap:anywhere}.name:hover{background:none;color:var(--accent)}.actions{display:flex;gap:8px;flex-wrap:wrap;min-width:235px}.actions button,.actions a{font-size:12px}#empty{padding:35px;text-align:center;color:var(--muted)}footer{display:flex;align-items:center;justify-content:space-between;margin-top:16px;gap:16px}dialog{background:var(--panel);color:var(--text);border:1px solid var(--line);border-radius:12px;width:min(760px,94vw);max-height:90vh;padding:24px}dialog::backdrop{background:#05090dc9}dialog h2{margin-top:0;overflow-wrap:anywhere}dialog label{display:block;margin-bottom:6px;color:var(--muted)}dialog input{width:100%}.dialog-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:20px}dl{display:grid;grid-template-columns:120px minmax(0,1fr);gap:10px}dt{color:var(--muted)}dd{margin:0;overflow-wrap:anywhere}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:var(--bg);padding:16px;max-height:350px;overflow:auto;border-radius:6px}#preview img{max-width:100%;max-height:50vh;display:block;margin:auto}#progress-panel[hidden]{display:none}.notice{font-size:13px;color:var(--muted)}@media(max-width:760px){header{padding:0 16px}.layout{grid-template-columns:1fr;height:auto}aside{max-height:210px;border-right:0;border-bottom:1px solid var(--line);padding:12px}aside h2{margin-bottom:6px}main{overflow:visible;padding:20px 16px}.toolbar input{margin-left:0;flex:1}header span{margin-left:10px}td,th{padding:12px}.date{display:none}table,tbody{display:block}thead{display:none}tr{display:grid;grid-template-columns:minmax(0,1fr) auto;border-top:1px solid var(--line)}tr:first-child{border-top:0}td{border:0}td:first-child{min-width:0;max-width:none}td:last-child{grid-column:1/-1;padding-top:0}.actions{min-width:0;flex-wrap:wrap}}
</style></head><body>
<header><div><strong>SPARK</strong><span>Shared files</span></div><a href="/api/docs">API reference ↗</a></header>
<div class="layout"><aside><h2>Directories</h2><nav id="folders" aria-label="File directories"></nav></aside>
<main><nav id="breadcrumb" aria-label="Breadcrumb"></nav><h1 id="heading">Files</h1><p class="muted">Shared across your devices.</p>
<div class="toolbar"><button id="upload" class="primary">Upload files</button><button id="mkdir">New folder</button><button id="refresh">Refresh</button><input id="filter" type="search" placeholder="Filter loaded files" aria-label="Filter loaded files"></div>
<input id="picker" type="file" multiple hidden><div id="drop"><strong>Drop files here</strong> or choose Upload files. Any file type, no upload size cap.</div>
<div id="progress-panel" hidden><label id="upload-label" for="progress">Uploading</label><progress id="progress" max="100" value="0"></progress><button id="cancel-upload">Cancel upload</button></div>
<p id="status" role="status" aria-live="polite">Loading files…</p><div class="table-wrap"><table><thead><tr><th>Name</th><th>Size</th><th class="date">Uploaded</th><th>Actions</th></tr></thead><tbody id="rows"></tbody></table><div id="empty" hidden></div></div>
<footer><span id="count" class="muted"></span><button id="more" hidden>Load more</button></footer><noscript>JavaScript is required to manage files here.</noscript>
</main></div>
<dialog id="edit"><form id="edit-form"><h2 id="edit-title"></h2><p id="edit-description"></p><label for="destination" id="destination-label">Directory</label><input id="destination" list="directory-options" autocomplete="off" required><datalist id="directory-options"></datalist><p id="edit-error" role="alert"></p><div class="dialog-actions"><button type="button" id="edit-cancel">Cancel</button><button type="submit" id="edit-submit" class="primary">Save</button></div></form></dialog>
<dialog id="details"><h2 id="detail-name"></h2><dl id="metadata"></dl><div id="preview"></div><div class="dialog-actions"><a id="detail-download" class="download">Download</a><button id="detail-close">Close</button></div></dialog>
<script>
'use strict';
const $=id=>document.getElementById(id);let directory='/',directories=[],files=[],hasMore=false,loading=false,busy=false,revision=0,editing=null,xhr=null,previewURL=null,previewAbort=null;
function el(tag,text,parent,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;if(parent)parent.appendChild(n);return n;}
function message(text,error=false){$('status').textContent=text;$('status').classList.toggle('error',error);}
function size(n){if(n<1024)return n+' B';const units=['KiB','MiB','GiB','TiB','PiB'];let i=-1;do{n/=1024;i++;}while(n>=1024&&i<units.length-1);return n.toFixed(1)+' '+units[i];}
async function api(path,options={}){const response=await fetch(path,{cache:'no-store',...options});if(!response.ok){let reason='HTTP '+response.status;try{reason=(await response.json()).error||reason;}catch{}throw new Error(reason.replaceAll('_',' '));}return response.status===204?null:response.json();}
function lock(value){busy=value;for(const id of ['upload','mkdir','refresh','more'])$(id).disabled=value;for(const n of document.querySelectorAll('.mutation'))n.disabled=value;}
function go(path){location.hash=encodeURIComponent(path);}
function directoryLink(path,label,parent){const a=el('a',label,parent);a.href='#'+encodeURIComponent(path);if(path===directory)a.setAttribute('aria-current','page');return a;}
function navigation(){ $('folders').replaceChildren();$('directory-options').replaceChildren();for(const path of directories){const a=directoryLink(path,path==='/'?'⌂  Root':path.split('/').pop(),$('folders'));a.style.paddingLeft=(12+Math.max(0,path.split('/').length-2)*14)+'px';a.title=path;const option=el('option',undefined,$('directory-options'));option.value=path;}$('breadcrumb').replaceChildren();directoryLink('/','Root',$('breadcrumb'));let path='';for(const part of directory.split('/').filter(Boolean)){el('span','/',$('breadcrumb'));path+='/'+part;directoryLink(path,part,$('breadcrumb'));}$('heading').textContent=directory==='/'?'Files':directory.split('/').pop();}
function render(){navigation();$('rows').replaceChildren();const query=$('filter').value.toLowerCase();let visible=0;const prefix=directory==='/'?'/':directory+'/';for(const path of directories){if(path===directory || !path.startsWith(prefix) || path.slice(prefix.length).includes('/'))continue;const name=path.slice(prefix.length);if(!name.toLowerCase().includes(query))continue;visible++;const row=el('tr',undefined,$('rows'));const cell=el('td',undefined,row);directoryLink(path,'▸  '+name,cell);el('td','Folder',row);el('td','',row,'date');el('td','',row);}
for(const file of files){if(!file.name.toLowerCase().includes(query))continue;visible++;const row=el('tr',undefined,$('rows'));const name=el('button',file.name,el('td',undefined,row),'name');name.addEventListener('click',()=>view(file));el('td',size(file.size_bytes),row);el('td',new Date(file.created_at).toLocaleString(),row,'date');const actions=el('div',undefined,el('td',undefined,row),'actions');const download=el('a','Download',actions,'download');download.href=file.download_url;download.download=file.name;const move=el('button','Move',actions,'mutation');move.disabled=busy;move.onclick=()=>edit('move',file);const remove=el('button','Delete',actions,'danger mutation');remove.disabled=busy;remove.onclick=()=>edit('delete',file);}
$('empty').hidden=visible>0;$('empty').textContent=query?'No matching files or folders in this view.':loading?'Loading…':'This folder is empty. Upload files or create a folder.';$('count').textContent=files.length+' files loaded'+(hasMore?' · more available':'');$('more').hidden=!hasMore;}
async function load(append=false){const token=++revision;loading=true;if(!append)files=[];render();message('Loading…');try{const query=new URLSearchParams({directory,limit:'100',offset:String(append?files.length:0)});const [page,folders]=await Promise.all([api('/files?'+query),api('/files/directories')]);if(token!==revision)return;files=append?files.concat(page.files):page.files;directories=folders.directories;hasMore=page.has_more;loading=false;render();message('');}catch(error){if(token!==revision)return;loading=false;render();message('Could not load files: '+error.message+'. Use Refresh to retry.',true);}}
function edit(kind,file){if(busy)return;editing={kind,file};$('edit-title').textContent=kind==='mkdir'?'New folder':kind==='move'?'Move '+file.name:'Delete '+file.name+'?';$('edit-description').textContent=kind==='delete'?'This permanently deletes the shared file for all devices.':kind==='move'?'Choose or enter the destination directory. Missing folders will be created.':'Enter a full directory path. Nested folders are supported.';$('destination').hidden=kind==='delete';$('destination-label').hidden=kind==='delete';$('destination').required=kind!=='delete';$('destination').value=kind==='move'?file.directory:directory==='/'?'/':directory+'/';$('edit-submit').textContent=kind==='delete'?'Delete permanently':kind==='move'?'Move file':'Create folder';$('edit-error').textContent='';$('edit').showModal();if(kind!=='delete')$('destination').focus();}
$('edit-form').onsubmit=async event=>{event.preventDefault();if(busy)return;const {kind,file}=editing;lock(true);$('edit-submit').disabled=true;try{if(kind==='delete')await api('/files/'+file.id,{method:'DELETE'});else await api(kind==='mkdir'?'/files/directories':'/files/'+file.id,{method:kind==='mkdir'?'POST':'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({directory:$('destination').value})});$('edit').close();await load();message(kind==='delete'?'File deleted.':kind==='move'?'File moved.':'Folder created.');}catch(error){$('edit-error').textContent=error.message;}finally{lock(false);$('edit-submit').disabled=false;}};
$('edit-cancel').onclick=()=>{if(!busy)$('edit').close();};$('edit').addEventListener('cancel',event=>{if(busy)event.preventDefault();});
function clearPreview(){if(previewAbort)previewAbort.abort();previewAbort=null;if(previewURL)URL.revokeObjectURL(previewURL);previewURL=null;}
async function view(file){clearPreview();$('detail-name').textContent=file.name;$('metadata').replaceChildren();for(const [key,value] of Object.entries({Directory:file.directory,Size:size(file.size_bytes)+' ('+file.size_bytes+' bytes)',Uploaded:new Date(file.created_at).toLocaleString(),ID:file.id})){el('dt',key,$('metadata'));el('dd',value,$('metadata'));}$('detail-download').href=file.download_url;$('detail-download').download=file.name;$('preview').replaceChildren();$('details').showModal();const ext=file.name.split('.').pop().toLowerCase();const images={png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg',gif:'image/gif',webp:'image/webp',bmp:'image/bmp',avif:'image/avif'};const text=['txt','md','json','csv','log','xml','html','css','js','cpp','hpp','c','h','sh','yaml','yml','ini','sql','svg'].includes(ext);if(!text && !(images[ext] && file.size_bytes<=10485760)){el('p','Preview unavailable for this file. Download to open it on your device.',$('preview'),'notice');return;}
const abort=new AbortController();previewAbort=abort;try{const response=await fetch(file.download_url,{headers:text&&file.size_bytes>65536?{Range:'bytes=0-65535'}:{},signal:abort.signal});if(!response.ok)throw new Error('HTTP '+response.status);if(text){const data=await response.text();if(abort.signal.aborted)return;el('pre',data,$('preview'));if(file.size_bytes>65536)el('p','Showing the first 64 KiB. Download for the complete file.',$('preview'),'notice');}else{const data=await response.blob();if(abort.signal.aborted)return;previewURL=URL.createObjectURL(new Blob([data],{type:images[ext]}));const image=el('img',undefined,$('preview'));image.alt=file.name;image.src=previewURL;image.onerror=()=>{image.remove();el('p','This image could not be previewed. Download to open it.',$('preview'));};}}catch(error){if(error.name!=='AbortError')el('p','Preview failed: '+error.message,$('preview'));}}
$('details').addEventListener('close',clearPreview);$('detail-close').onclick=()=>$('details').close();
function send(file,target){return new Promise((resolve,reject)=>{xhr=new XMLHttpRequest();xhr.open('POST','/files?'+new URLSearchParams({name:file.name,directory:target}));xhr.setRequestHeader('Content-Type','application/octet-stream');xhr.upload.onprogress=event=>{if(event.lengthComputable)$('progress').value=event.loaded/event.total*100;};xhr.onload=()=>{if(xhr.status===201)resolve();else{let reason='HTTP '+xhr.status;try{reason=JSON.parse(xhr.responseText).error||reason;}catch{}reject(new Error(reason.replaceAll('_',' ')));}};xhr.onerror=()=>reject(new Error('Connection lost; refresh to check whether the upload completed.'));xhr.onabort=()=>reject(new Error('Upload cancelled; refresh to check whether it already completed.'));xhr.send(file);});}
async function upload(selected){if(busy||!selected.length)return;lock(true);const target=directory;let completed=0;$('progress-panel').hidden=false;try{for(const file of selected){$('upload-label').textContent='Uploading '+file.name+' to '+target;$('progress').value=0;await send(file,target);completed++;}await load();message(completed+' file(s) uploaded to '+target+'.');}catch(error){await load();message(completed+' file(s) uploaded. '+error.message,true);}finally{xhr=null;$('progress-panel').hidden=true;$('picker').value='';lock(false);}}
$('upload').onclick=()=>$('picker').click();$('picker').onchange=()=>upload(Array.from($('picker').files));$('cancel-upload').onclick=()=>{if(xhr)xhr.abort();};$('mkdir').onclick=()=>edit('mkdir');$('refresh').onclick=()=>load();$('filter').oninput=render;$('more').onclick=()=>{if(!loading)load(true);};
for(const type of ['dragenter','dragover'])$('drop').addEventListener(type,event=>{event.preventDefault();$('drop').classList.add('drag');});$('drop').ondragleave=()=>$('drop').classList.remove('drag');$('drop').ondrop=event=>{event.preventDefault();$('drop').classList.remove('drag');upload(Array.from(event.dataTransfer.files));};
function locationChanged(){try{directory=decodeURIComponent(location.hash.slice(1))||'/';}catch{directory='/';}$('filter').value='';load();}window.addEventListener('hashchange',locationChanged);locationChanged();
</script></body></html>)HTML";
}
